import{_ as a,C as i,c as g,o as l,a3 as o,G as n,j as e,a as s}from"./chunks/framework.Dokpd4od.js";const P=JSON.parse('{"title":"Manufacturing orders","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/workflows/manufacturing-orders.md","filePath":"master/supply-chain/manufacturing/workflows/manufacturing-orders.md","lastUpdated":1793074831000}'),d={name:"master/supply-chain/manufacturing/workflows/manufacturing-orders.md"};function u(h,t,c,m,p,f){const r=i("ImagePopup");return l(),g("div",null,[t[0]||(t[0]=o('<h1 id="manufacturing-orders" tabindex="-1">Manufacturing orders <a class="header-anchor" href="#manufacturing-orders" aria-label="Permalink to &quot;Manufacturing orders&quot;">​</a></h1><p>A manufacturing order (MO) is the instruction to make a product. It names the product, the quantity, the recipe (bill of materials) and the date. From it, Aureus reserves the components, creates the work orders and records the finished goods in stock.</p><blockquote><p><strong>In simple words:</strong> An MO says &quot;make 5 Business Laptops, using this recipe, starting on this date&quot;.</p></blockquote><p>Open <code>Manufacturing → Operations → Manufacturing Orders</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Work Orders</strong> tab on the MO form and the <strong>Work Orders</strong> menu appear only when <strong>Work Orders</strong> is on. Go to <code>Manufacturing → Settings → Manage Operations</code>. See <a href="./../get-started/manufacturing-settings.html">Manufacturing settings</a>.</p><p>You also need a product with a bill of materials. See <a href="./../basic-setup/bill-of-materials.html">Bill of materials</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2>',8)),n(r,{src:"/images1/manufacturing/mo_list.png",alt:"Manufacturing Orders list with MO/1 (Draft) and MO/2 (Confirmed), tabs row visible, columns Reference to State"}),t[1]||(t[1]=o('<p>The list has these parts.</p><ul><li><strong>Tabs:</strong> <strong>Default</strong>, <strong>To Do</strong>, <strong>Done</strong>, <strong>Cancelled</strong>, <strong>Planned</strong>, <strong>MO Pending</strong>, <strong>MO Ready</strong>, <strong>My MOs</strong>, <strong>Late</strong>.</li><li><strong>Columns:</strong> <strong>Reference</strong>, <strong>Start</strong>, <strong>Product</strong>, <strong>Source</strong>, <strong>MO Readiness</strong>, <strong>Quantity</strong>, <strong>UoM</strong>, <strong>Company</strong>, <strong>State</strong>. You can also show <strong>End</strong>, <strong>Deadline</strong>, <strong>Lot/Serial Number</strong>, <strong>Bill of Material</strong>, <strong>Responsible</strong>, <strong>Component Status</strong>, <strong>Consumption Efficiency</strong>, <strong>Expected Duration</strong> and <strong>Real Duration</strong>.</li><li><strong>Group by:</strong> <strong>State</strong>, <strong>Product</strong>, <strong>Bill of Material</strong>, <strong>Responsible</strong>, <strong>Deadline</strong>.</li><li><strong>Row actions:</strong> <strong>View</strong>, <strong>Edit</strong>, <strong>Delete</strong>.</li></ul><p><strong>MO Readiness</strong> tells you if the order can start.</p><table tabindex="0"><thead><tr><th>Readiness</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Waiting</strong></td><td>Components are missing.</td></tr><tr><td><strong>Ready</strong></td><td>Components are reserved.</td></tr><tr><td><strong>Waiting another operation</strong></td><td>A work order waits for an earlier one.</td></tr></tbody></table><h2 id="create-a-manufacturing-order" tabindex="-1">Create a manufacturing order <a class="header-anchor" href="#create-a-manufacturing-order" aria-label="Permalink to &quot;Create a manufacturing order&quot;">​</a></h2><p>Scenario: make 5 <strong>Business Laptop</strong> with <strong>BOM-MC-LAPTOP</strong>.</p><ol><li>Click <strong>Create Manufacturing Order</strong>.</li></ol>',7)),n(r,{src:"/images1/manufacturing/mo_create_button.png",alt:"Manufacturing Orders list with the Create Manufacturing Order button highlighted"}),t[2]||(t[2]=e("ol",{start:"2"},[e("li",null,[s("Fill the "),e("strong",null,"General"),s(" section.")])],-1)),n(r,{src:"/images1/manufacturing/mo_create_general.png",alt:"Create form filled: Product Business Laptop, Quantity 5, UoM Units, Bill of Material BOM-MC-LAPTOP, Scheduled Date, Responsible ERP Admin; crop on General section"}),t[3]||(t[3]=o('<ul><li><strong><em>Product:</em></strong> The goods you make. Pick a product with a bill of materials.</li><li><strong><em>Quantity:</em></strong> How many units to make. Required.</li><li><strong><em>Quantity Producing:</em></strong> How many you finished so far. It is hidden while the MO is <strong>Draft</strong>. See <a href="./produce-and-consume.html">Produce and consume</a>.</li><li><strong><em>UoM:</em></strong> The unit for the quantity. It follows the product.</li><li><strong><em>Bill of Material:</em></strong> The recipe. It fills in when the product has one.</li><li><strong><em>Scheduled Date:</em></strong> When production should start. Required.</li><li><strong><em>Scheduled End:</em></strong> When production should end. You cannot edit it. Aureus fills it in when you plan the order.</li><li><strong><em>Responsible:</em></strong> The user in charge.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Change the product, bill of materials, quantity or UoM and Aureus rebuilds the <strong>Components</strong> and <strong>Work Orders</strong> tabs from the recipe.</p></div><ol start="3"><li>Open the <strong>Components</strong> tab and check the list.</li></ol>',3)),n(r,{src:"/images1/manufacturing/mo_create_components.png",alt:"Components tab with the six laptop components for quantity 5 (To Consume 5 each)"}),t[4]||(t[4]=o('<ul><li><strong><em>Product:</em></strong> The component.</li><li><strong><em>From:</em></strong> The location it is taken from.</li><li><strong><em>To Consume:</em></strong> The amount the recipe needs for this quantity.</li><li><strong><em>Quantity:</em></strong> The amount actually used.</li><li><strong><em>UoM:</em></strong> The unit.</li><li><strong><em>Forecast:</em></strong> The expected stock position of the component.</li></ul><p>Click <strong>Add a line</strong> to add one more component for this order only.</p><ol start="4"><li>Open the <strong>Work Orders</strong> tab. It lists one row for each operation of the recipe.</li></ol>',3)),n(r,{src:"/images1/manufacturing/mo_create_work_orders.png",alt:"Work Orders tab with Assemble Components and Test & Pack rows"}),t[5]||(t[5]=o('<p>The columns are <strong>Operation</strong>, <strong>Work Center</strong>, <strong>Product</strong>, <strong>Quantity Remaining</strong>, <strong>Start</strong>, <strong>End</strong>, <strong>Expected Duration</strong>, <strong>Real Duration</strong> and <strong>Status</strong>. Each row has icon buttons to start, pause and finish. See <a href="./work-orders.html">Work orders</a>.</p><ol start="5"><li>Open the <strong>Miscellaneous</strong> tab.</li></ol>',2)),n(r,{src:"/images1/manufacturing/mo_create_misc.png",alt:"Miscellaneous tab with Operation Type, Source, Finished Products Location, Company"}),t[6]||(t[6]=o('<ul><li><strong><em>Operation Type:</em></strong> The warehouse operation that records the production.</li><li><strong><em>Source:</em></strong> The document or reason behind this order.</li><li><strong><em>Finished Products Location:</em></strong> Where the finished goods are stored.</li><li><strong><em>Company:</em></strong> The owner company.</li></ul><ol start="6"><li>Click <strong>Create</strong>. The MO is saved as <strong>Draft</strong>, for example <strong>MO/1</strong>.</li></ol><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2>',3)),n(r,{src:"/images1/manufacturing/mo_view_confirmed.png",alt:"MO/2 view page in Confirmed state: state bar and header buttons Produce All, Plan, Start, Cancel, Print visible"}),t[7]||(t[7]=o(`<p>The state bar shows <strong>Draft</strong>, <strong>Confirmed</strong> and <strong>Done</strong>. <strong>In Progress</strong>, <strong>To Close</strong> and <strong>Cancelled</strong> appear when the order is in that state.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Draft → Confirmed → In Progress → To Close → Done</span></span>
<span class="line"><span>              └──────→ Cancelled</span></span></code></pre></div><table tabindex="0"><thead><tr><th>State</th><th>Buttons</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Draft</strong></td><td><strong>Confirm</strong></td><td>Nothing is reserved yet.</td></tr><tr><td><strong>Confirmed</strong></td><td><strong>Produce All</strong>, <strong>Plan</strong>, <strong>Start</strong>, <strong>Cancel</strong>, <strong>Print</strong></td><td>Components are reserved. Work orders exist.</td></tr><tr><td><strong>In Progress</strong></td><td><strong>Produce All</strong> or <strong>Produce</strong>, <strong>Cancel</strong>, <strong>Print</strong></td><td>Work has started.</td></tr><tr><td><strong>To Close</strong></td><td><strong>Produce All</strong> or <strong>Produce</strong>, <strong>Cancel</strong>, <strong>Print</strong></td><td>All work orders are finished. Close the MO.</td></tr><tr><td><strong>Done</strong></td><td>None</td><td>The MO is locked.</td></tr><tr><td><strong>Cancelled</strong></td><td>None</td><td>The MO is closed.</td></tr></tbody></table><h3 id="confirm" tabindex="-1">Confirm <a class="header-anchor" href="#confirm" aria-label="Permalink to &quot;Confirm&quot;">​</a></h3><p>Click <strong>Confirm</strong> and confirm the prompt. The stock moves and the transfers are confirmed. The state becomes <strong>Confirmed</strong>. You see <strong>Manufacturing order confirmed</strong>.</p><h3 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;Start&quot;">​</a></h3><p>Click <strong>Start</strong>. The state becomes <strong>In Progress</strong>. You see <strong>Manufacturing order started</strong>.</p><h3 id="plan-and-unplan" tabindex="-1">Plan and Unplan <a class="header-anchor" href="#plan-and-unplan" aria-label="Permalink to &quot;Plan and Unplan&quot;">​</a></h3><p><strong>Plan</strong> puts the work orders on the calendar of their work centers. <strong>Unplan</strong> removes those dates. See <a href="./plan-and-schedule.html">Plan and schedule</a>.</p><h3 id="produce" tabindex="-1">Produce <a class="header-anchor" href="#produce" aria-label="Permalink to &quot;Produce&quot;">​</a></h3><p><strong>Produce All</strong> completes the order. See <a href="./produce-and-consume.html">Produce and consume</a>.</p><h3 id="cancel" tabindex="-1">Cancel <a class="header-anchor" href="#cancel" aria-label="Permalink to &quot;Cancel&quot;">​</a></h3><p>Click <strong>Cancel</strong>. Open work orders, stock moves and transfers are cancelled. The state becomes <strong>Cancelled</strong>. You see <strong>Manufacturing order cancelled</strong>. Finished work orders stay as they are.</p><h3 id="print" tabindex="-1">Print <a class="header-anchor" href="#print" aria-label="Permalink to &quot;Print&quot;">​</a></h3><p>Click <strong>Print</strong> and choose one option.</p><ul><li><strong>Print MO:</strong> downloads the order as a PDF.</li><li><strong>Print Labels:</strong> asks for <strong>Quantity To Print</strong> (<strong>Operation Quantity</strong> or <strong>Custom Quantity</strong>), a <strong>Quantity</strong> from 1 to 100 and a <strong>Format</strong>. Formats are <strong>Dymo</strong>, <strong>2x7 with price</strong>, <strong>4x7 with price</strong>, <strong>4x12</strong> and <strong>4x12 with price</strong>.</li></ul>`,16)),n(r,{src:"/images1/manufacturing/mo_print_labels.png",alt:"Print menu open and the Print Labels modal with Quantity To Print, Quantity and Format fields filled"}),t[8]||(t[8]=e("h2",{id:"overview-and-transfers-pages",tabindex:"-1"},[s("Overview and Transfers pages "),e("a",{class:"header-anchor",href:"#overview-and-transfers-pages","aria-label":'Permalink to "Overview and Transfers pages"'},"​")],-1)),t[9]||(t[9]=e("p",null,"Every MO has two extra pages in its sub navigation.",-1)),t[10]||(t[10]=e("p",null,[e("strong",null,"Overview"),s(" shows costs and stock for each line.")],-1)),n(r,{src:"/images1/manufacturing/mo_overview.png",alt:"MO/2 Overview page with the product table, Operations row and Unit Cost total"}),t[11]||(t[11]=o('<ul><li><strong>Columns:</strong> <strong>Product</strong>, <strong>Status</strong>, <strong>Quantity</strong>, <strong>Free to use / On Hand</strong>, <strong>Reserved</strong>, <strong>Receipt</strong>, <strong>Unit Cost</strong>, <strong>MO Cost</strong>, <strong>BoM Cost</strong>, <strong>Real Cost</strong>.</li><li><strong>Operations:</strong> a row in minutes for each work order.</li><li><strong>Unit Cost:</strong> the total at the bottom.</li></ul><p>See <a href="./../basic-setup/manufacturing-order-costs.html">Manufacturing order costs</a>.</p><p><strong>Transfers</strong> lists the stock transfers linked to the MO, for example the pick transfer <strong>WH/PC/16</strong> with state <strong>Ready</strong>. With a three step warehouse it also lists the store transfer.</p>',3)),n(r,{src:"/images1/manufacturing/mo_transfers.png",alt:"MO/2 Transfers page showing the linked pick transfer WH/PC/16 in Ready state"}),t[12]||(t[12]=o('<h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>MO numbers run MO/1, MO/2 and so on. Pick transfers use the prefix <strong>WH/PC</strong>. Store transfers use <strong>SFP</strong>.</p><p>Components move from <strong>Stock</strong> to <strong>Pre-Production</strong>, then to <strong>Production</strong> when used. Finished goods move from <strong>Production</strong> to <strong>Stock</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./plan-and-schedule.html">Plan and schedule</a></li><li><a href="./work-orders.html">Work orders</a></li><li><a href="./produce-and-consume.html">Produce and consume</a></li><li><a href="./../basic-setup/bill-of-materials.html">Bill of materials</a></li><li><a href="./../../inventories/warehouses/warehouses.html">Warehouses</a></li></ul>',5))])}const T=a(d,[["render",u]]);export{P as __pageData,T as default};
